#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>

using namespace std;

/**
 * Problem: 24731 - Roads in the North
 * 
 * 解題思路：
 * 1. 題目給定一個無向連通圖，且任兩點間只有一條路徑，這表示該圖是一棵樹。
 * 2. 任務是尋找樹中最遠兩點的距離，即樹的直徑 (Tree Diameter)。
 * 3. 演算法：
 *    - 任選一個起點（例如節點 1）。
 *    - 執行第一次 DFS 找到距離起點最遠的節點 u。
 *    - 從節點 u 開始執行第二次 DFS 找到距離 u 最遠的距離，該距離即為樹的直徑。
 */

struct Edge {
    int to, weight;
};

vector<vector<Edge>> adj_list;
int current_max_dist, best_node;

void find_farthest(int u, int p, int dist) {
    if (dist > current_max_dist) {
        current_max_dist = dist;
        best_node = u;
    }
    for (auto& e : adj_list[u]) {
        if (e.to != p) {
            find_farthest(e.to, u, dist + e.weight);
        }
    }
}

int main() {
    string line;
    while (true) {
        adj_list.assign(10001, vector<Edge>());
        bool has_data = false;
        while (getline(cin, line) && !line.empty()) {
            has_data = true;
            stringstream ss(line);
            int u, v, w;
            ss >> u >> v >> w;
            adj_list[u].push_back({v, w});
            adj_list[v].push_back({u, w});
        }

        if (!has_data) break;

        current_max_dist = -1;
        find_farthest(1, -1, 0);

        int start_node = best_node;
        current_max_dist = -1;
        find_farthest(start_node, -1, 0);

        cout << current_max_dist << endl;
    }
    return 0;
}
